import glob

base = "pkg/cmd"
remaining = []
for fpath in sorted\(glob.glob\(f"{base}/**/*.go", recursive=True\)\):
    if fpath.endswith\("_test.go"\):
        continue
    with open\(fpath\) as f:
        for i, line in enumerate\(f, 1\):
            s = line.strip\(\)
            if s.startswith\("Short:"\):
                for q in ['"', '`']:
                    prefix = f"Short: {q}"
                    if s.startswith\(prefix\):
                        text = s[len\(prefix\):s.rindex\(q\)]
                        has_chinese = any\('\\u4e00' <= c <= '\\u9fff' for c in text\)
                        if not has_chinese and len\(text\) > 3:
                            remaining.append\(\(fpath, i, text\)\)
                        break

print\(f"Remaining English Short descriptions \({len\(remaining\)}\):"\)
for f, line, text in remaining:
    print\(f"  {f}:{line}: {text}"\)
